const fullResponse = items[0].json.content.parts[0].text;
const paciente = $('Extraer Campos del Paciente').first().json;

return [{
  json: {
    ...paciente,
    sintomas: 'ANALISIS DE IMAGEN MEDICA:\n' + fullResponse.replace(/\*+/g, '').replace(/#+/g, '').replace(/\n{3,}/g, '\n\n').trim().substring(0, 800)
  }
}];

const fullResponse = items[0].json.content.parts[0].text;
const paciente = $('Extraer Campos del Paciente').first().json;

// Extraer solo la transcripcion limpia
let transcripcion = fullResponse;
const match = fullResponse.match(/[""](.+?)[""]/s);
if (match) {
  transcripcion = match[1].trim();
}

return [{
  json: {
    ...paciente,
    sintomas: 'Audio: ' + transcripcion
  }
}];

const paciente = items.reduce((prev, curr) => {
  const prevLen = (prev.json.sintomas || '').length;
  const currLen = (curr.json.sintomas || '').length;
  return currLen > prevLen ? curr : prev;
}).json;

return [{ json: paciente }];

parameters.text:
=Sos un sistema experto de triaje hospitalario basado en el Manchester Triage System.

PACIENTE:
Nombre: {{ $json.nombre }}
Edad: {{ $json.edad }}
Sintomas: {{ $json.sintomas }}

Usando el contexto medico disponible, clasificá este caso y respondé SOLO con este JSON sin comillas triples ni texto adicional:
{"urgencia": "CRITICO|MODERADO|LEVE|REVISION", "diagnostico": "diagnostico presuntivo", "especialidad": "especialidad recomendada", "confianza": 0.95, "justificacion": "justificacion clinica breve"}

Cuando recibas un ANALISIS DE IMAGEN MEDICA, clasificá según la severidad descripta en el análisis usando los mismos criterios del Manchester Triage System.

IMPORTANTE: respondé SOLO con el objeto JSON puro, sin comillas triples, sin bloques de codigo, sin texto antes ni despues.

parameters.jsCode:
const raw = items[0].json.output;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const jsonString = raw.substring(start, end + 1);

let clasificacion;
try {
  clasificacion = JSON.parse(jsonString);
} catch(e) {
  clasificacion = {
    urgencia: 'REVISION',
    diagnostico: 'Error de parseo',
    especialidad: 'General',
    confianza: 0,
    justificacion: 'No se pudo parsear la respuesta de la IA'
  };
}

const paciente = $('Seleccionar Datos Enriquecidos').first().json;

return [{
  json: {
    ...paciente,
    ia_urgencia: clasificacion.urgencia,
    ia_diagnostico: clasificacion.diagnostico,
    ia_especialidad: clasificacion.especialidad,
    ia_confianza: clasificacion.confianza,
    ia_justificacion: clasificacion.justificacion,
    timestamp_procesamiento: new Date().toISOString()
  }
}];

